def find_mode(root):
    prev = None
    count = max_count = 0
    modes = []
    def inorder(node):
        nonlocal prev, count, max_count, modes
        if not node:
            return
        inorder(node.left)
        if prev is not None and node.val == prev:
            count += 1                             # extend the current streak
        else:
            count = 1                                # reset the streak
        if count > max_count:
            max_count = count
            modes = [node.val]                        # new sole mode
        elif count == max_count:
            modes.append(node.val)                     # tie, add to modes
        prev = node.val
        inorder(node.right)
    inorder(root)
    return modes

