public class Main {
    static Integer prev = null;
    static int count = 0, maxCount = 0;
    static List<Integer> modes = new ArrayList<>();
    static void inorder(TreeNode node) {
        if (node == null) return;
        inorder(node.left);
        if (prev != null && node.val == prev) count++;         // extend the current streak
        else count = 1;                                          // reset the streak
        if (count > maxCount) { maxCount = count; modes = new ArrayList<>(List.of(node.val)); }  // new sole mode
        else if (count == maxCount) modes.add(node.val);           // tie, add to modes
        prev = node.val;
        inorder(node.right);
    }
}

