bool hasPrev = false;
vector<int> modes;
void inorder(TreeNode* node) {
    if (!node) return;
    inorder(node->left);
    if (hasPrev && node->val == prevVal) count++;               // extend the current streak
    else count = 1;                                                // reset the streak
    if (count > maxCount) { maxCount = count; modes = {node->val}; }  // new sole mode
    else if (count == maxCount) modes.push_back(node->val);           // tie, add to modes
    prevVal = node->val; hasPrev = true;
    inorder(node->right);
}
